import { REPLY_STYLE_INSTRUCTIONS } from './reply-style.js';
import { createSkillRuntime, skillToolDefinitions, skillRuntimeInstructions } from './carb-skill-runtime.js';
import { globalSkillsRoot } from './carb-global-skills.js';
import { artifactOutputReceipt, artifactTaskInstructions, verifyArtifactSet } from './carb-artifact-evidence.js';
import { documentDigest, verifyDocumentReadback } from './carb-document-evidence.js';
import { EventEmitter } from 'node:events';
import { randomUUID } from 'node:crypto';
import { spawn } from 'node:child_process';
import { link, lstat, mkdir, open, opendir, realpath, rename, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';

const MAX_RESPONSE_BYTES = 8 * 1024 * 1024;
const MAX_FILE_BYTES = 1024 * 1024;
const MAX_TOOL_OUTPUT = 16_000;
const MAX_DIRECTORY_ENTRIES = 150;
const SERVICE_IDLE_MS = 120_000;
const TOOL_DEFINITIONS = [
  ...skillToolDefinitions,
  {
    type: 'function',
    function: {
      name: 'artifact_inspect',
      description: 'Verify exactly one PPTX, DOCX, XLSX, Python and Markdown output in the active workspace. Returns byte counts, SHA-256 and required Office package entries.',
      parameters: { type: 'object', properties: { paths: { type: 'array', minItems: 5, maxItems: 5, items: { type: 'string' } } }, required: ['paths'], additionalProperties: false },
    },
  },
  {
    type: 'function',
    function: {
      name: 'request_user_input',
      description: 'Ask up to three task clarification questions and wait for the user. Offer two to four meaningful options when useful; a separate custom answer is always available. Use only when the answer materially affects the work.',
      parameters: {
        type: 'object', properties: { questions: { type: 'array', minItems: 1, maxItems: 3, items: {
          type: 'object', properties: {
            id: { type: 'string' }, header: { type: 'string' }, question: { type: 'string' },
            multiSelect: { type: 'boolean' }, secret: { type: 'boolean' },
            options: { type: 'array', maxItems: 4, items: { type: 'object', properties: { label: { type: 'string' }, description: { type: 'string' } }, required: ['label'], additionalProperties: false } }
          }, required: ['id', 'question'], additionalProperties: false
        } } }, required: ['questions'], additionalProperties: false
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'read_file',
      description: 'Read UTF-8 text inside the active workspace or an explicitly attached file. Large files can be read in pages using start_line and start_column (both 1-based). The result provides the cursor for the next page.',
      parameters: { type: 'object', properties: { path: { type: 'string' }, start_line: { type: 'integer', minimum: 1 }, start_column: { type: 'integer', minimum: 1 } }, required: ['path'], additionalProperties: false },
    },
  },
  {
    type: 'function',
    function: {
      name: 'write_file',
      description: 'Create or replace a text file inside the active workspace.',
      parameters: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'], additionalProperties: false },
    },
  },
  {
    type: 'function',
    function: {
      name: 'run_command',
      description: 'Run a shell command in the active workspace. Windows uses cmd.exe: group paths and arguments with double quotes; single quotes do not group arguments. Other platforms use /bin/sh. Write complex or multiline code to a script file before running it.',
      parameters: { type: 'object', properties: { command: { type: 'string' } }, required: ['command'], additionalProperties: false },
    },
  },
  {
    type: 'function',
    function: {
      name: 'list_directory',
      description: 'List files and folders in one directory inside the active workspace. Use . for the workspace root.',
      parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false },
    },
  },
];

const now = () => Date.now();
const asText = (value) => typeof value === 'string' ? value : JSON.stringify(value);

function safeApiUrl(baseUrl) {
  const url = new URL(baseUrl);
  if (url.protocol !== 'https:' && !(url.protocol === 'http:' && url.hostname === '127.0.0.1')) {
    throw new Error('Model connection must use HTTPS or loopback HTTP.');
  }
  if (url.username || url.password) throw new Error('Credentials must not be embedded in the model connection URL.');
  return url;
}

function endpointUrl(baseUrl, endpoint) {
  const url = safeApiUrl(baseUrl);
  const pathName = url.pathname.replace(/\/+$/u, '');
  url.pathname = pathName.endsWith(`/${endpoint}`) ? pathName : `${pathName}/${endpoint}`;
  return url;
}

function responseTools(tools) {
  return tools.map(({ function: tool }) => ({
    type: 'function',
    name: tool.name,
    description: tool.description,
    parameters: tool.parameters,
    strict: false,
  }));
}

function anthropicTools(tools) {
  return tools.map(({ function: tool }) => ({
    name: tool.name,
    description: tool.description,
    input_schema: tool.parameters,
  }));
}

function responseInput(messages) {
  const instructions = [];
  const input = [];
  for (const message of messages) {
    if (message.role === 'system') {
      if (message.content) instructions.push(message.content);
    } else if (message.role === 'user') {
      input.push({ role: 'user', content: [{ type: 'input_text', text: asText(message.content) }] });
    } else if (message.role === 'assistant') {
      if (message.content) input.push({ role: 'assistant', content: [{ type: 'output_text', text: asText(message.content) }] });
      for (const call of message.tool_calls ?? []) {
        input.push({ type: 'function_call', call_id: call.id, name: call.function.name, arguments: call.function.arguments });
      }
    } else if (message.role === 'tool') {
      input.push({ type: 'function_call_output', call_id: message.tool_call_id, output: asText(message.content) });
    }
  }
  return { instructions: instructions.join('\n\n'), input };
}

function anthropicInput(messages) {
  const system = [];
  const input = [];
  for (const message of messages) {
    if (message.role === 'system') {
      if (message.content) system.push(asText(message.content));
    } else if (message.role === 'user') {
      input.push({ role: 'user', content: asText(message.content) });
    } else if (message.role === 'assistant') {
      const content = [];
      if (message.content) content.push({ type: 'text', text: asText(message.content) });
      for (const call of message.tool_calls ?? []) {
        let inputValue = {};
        try { inputValue = JSON.parse(call.function.arguments || '{}'); } catch {}
        content.push({ type: 'tool_use', id: call.id, name: call.function.name, input: inputValue });
      }
      if (content.length) input.push({ role: 'assistant', content });
    } else if (message.role === 'tool') {
      const result = { type: 'tool_result', tool_use_id: message.tool_call_id, content: asText(message.content) };
      const previous = input.at(-1);
      if (previous?.role === 'user' && Array.isArray(previous.content)) previous.content.push(result);
      else input.push({ role: 'user', content: [result] });
    }
  }
  return { system: system.join('\n\n'), messages: input };
}

function requestFor(connection, apiKey, model, messages, document, effort) {
  const tools = document ? TOOL_DEFINITIONS.filter(tool => tool.function.name !== 'run_command') : TOOL_DEFINITIONS;
  if (connection.transport === 'openai-compatible') {
    return {
      url: endpointUrl(connection.baseUrl, 'chat/completions'),
      headers: { Authorization: `Bearer ${apiKey}` },
      // Sending tools defaults to automatic tool selection; omitting the optional
      // tool_choice field also works with DeepSeek thinking-mode gateways.
      body: { model, messages, tools, stream: true, ...(effort && effort !== 'auto' ? { reasoning_effort: effort } : {}) },
    };
  }
  if (connection.transport === 'openai-responses') {
    const input = responseInput(messages);
    return {
      url: endpointUrl(connection.baseUrl, 'responses'),
      headers: { Authorization: `Bearer ${apiKey}` },
      body: {
        model,
        ...(input.instructions ? { instructions: input.instructions } : {}),
        input: input.input,
        ...(effort && effort !== 'auto' ? { reasoning: { effort } } : {}),
        tools: responseTools(tools),
        tool_choice: 'auto',
        stream: true,
      },
    };
  }
  if (connection.transport === 'anthropic-messages') {
    const input = anthropicInput(messages);
    return {
      url: endpointUrl(connection.baseUrl, 'messages'),
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
      body: {
        model,
        max_tokens: 4096,
        ...(effort && effort !== 'auto' ? { output_config: { effort } } : {}),
        ...(input.system ? { system: input.system } : {}),
        messages: input.messages,
        tools: anthropicTools(tools),
        stream: true,
      },
    };
  }
  throw new Error('The selected model connection uses an unsupported transport.');
}

function emptyAssistantMessage() { return { content: '', tool_calls: [] }; }

function appendToolCall(message, index, { id, name, nameDelta = false, arguments: argumentDelta, input } = {}) {
  if (!Number.isSafeInteger(index) || index < 0 || index > 1024) throw new Error('The provider returned an invalid tool call index.');
  const current = message.tool_calls[index] ?? { id: '', type: 'function', function: { name: '', arguments: '' } };
  if (typeof id === 'string' && id) current.id = id;
  if (typeof name === 'string' && name && (!nameDelta || name !== current.function.name)) {
    current.function.name = nameDelta ? current.function.name + name : name;
  }
  if (typeof argumentDelta === 'string') current.function.arguments += argumentDelta;
  if (input !== undefined) current.function.arguments = typeof input === 'string' ? input : JSON.stringify(input);
  message.tool_calls[index] = current;
}

function restoreMessages(saved, defaultInstructions) {
  if (!Array.isArray(saved) || !saved.length) return [{ role: 'system', content: defaultInstructions }];
  const restored = [];
  for (const item of saved) {
    if (!item || !['system', 'user', 'assistant', 'tool'].includes(item.role) || typeof item.content !== 'string') continue;
    if (item.role === 'tool') {
      if (typeof item.tool_call_id === 'string') restored.push({ role: 'tool', tool_call_id: item.tool_call_id, content: item.content });
      continue;
    }
    if (item.role === 'assistant') {
      const toolCalls = Array.isArray(item.tool_calls) ? item.tool_calls.filter((call) =>
        call && typeof call.id === 'string' && call.function && typeof call.function.name === 'string' && typeof call.function.arguments === 'string')
        .map((call) => ({ id: call.id, type: 'function', function: { name: call.function.name, arguments: call.function.arguments } })) : [];
      restored.push({ role: item.role, content: item.content, ...(toolCalls.length ? { tool_calls: toolCalls } : {}),
        ...(typeof item.reasoning_content === 'string' ? { reasoning_content: item.reasoning_content } : {}) });
    } else {
      restored.push({ role: item.role, content: item.content });
    }
  }
  if (!restored.some((item) => item.role === 'system')) restored.unshift({ role: 'system', content: defaultInstructions });
  return restored.length > 0 ? restored : [{ role: 'system', content: defaultInstructions }];
}

async function resolveWorkspacePath(workspacePath, requestedPath, { allowMissing = false, directory = false } = {}) {
  if (typeof requestedPath !== 'string' || !requestedPath.trim() || requestedPath.includes('\0')) throw new Error('A workspace path is required.');
  if (process.platform === 'win32' && (/^[/\\]{2}[?.]/u.test(requestedPath) || requestedPath.replace(/^[a-z]:/iu, '').includes(':'))) {
    throw new Error('Device paths and alternate data streams are not supported by workspace tools.');
  }
  const root = await realpath(workspacePath);
  const absolute = path.resolve(root, requestedPath);
  const relative = path.relative(root, absolute);
  if ((!relative && !directory) || relative === '..' || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
    throw new Error('The path must stay inside the active workspace.');
  }
  if (!relative) return root;
  const pieces = relative.split(path.sep).filter(Boolean);
  if (process.platform === 'win32' && pieces.some(part => /[ .]$/u.test(part) || /^(?:CON|PRN|AUX|NUL|COM[1-9¹²³]|LPT[1-9¹²³])(?:\.|$)/iu.test(part))) {
    throw new Error('Device names and paths with trailing spaces or periods are not supported by workspace tools.');
  }
  let cursor = root;
  for (let i = 0; i < pieces.length; i += 1) {
    cursor = path.join(cursor, pieces[i]);
    let info;
    try { info = await lstat(cursor); }
    catch (error) {
      if (allowMissing && error?.code === 'ENOENT') break;
      throw error;
    }
    if (info.isSymbolicLink()) throw new Error('Symbolic links are not accessible through workspace tools.');
    if (i < pieces.length - 1 || directory) {
      if (!info.isDirectory()) throw new Error('The path is not a directory.');
    } else if (!info.isFile() || info.nlink > 1) {
      throw new Error('Only regular files without hard links can be read or replaced.');
    }
  }
  const realAbsolute = await realpath(path.dirname(absolute)).catch((error) => {
    if (allowMissing && error?.code === 'ENOENT') return undefined;
    throw error;
  });
  if (realAbsolute) {
    const parentRelative = path.relative(root, realAbsolute);
    if (parentRelative === '..' || parentRelative.startsWith(`..${path.sep}`) || path.isAbsolute(parentRelative)) {
      throw new Error('The file path resolves outside the active workspace.');
    }
  }
  return absolute;
}

async function readTextFile(filename, signal) {
  signal.throwIfAborted();
  const file = await open(filename, 'r');
  try {
    const info = await file.stat();
    if (!info.isFile() || info.nlink > 1) throw new Error('Only regular files without hard links can be read.');
    if (info.size > MAX_FILE_BYTES) throw new Error('The requested file is larger than 1 MB.');
    const bytes = Buffer.allocUnsafe(info.size + 1);
    let offset = 0;
    while (offset < bytes.length) {
      signal.throwIfAborted();
      const { bytesRead } = await file.read(bytes, offset, bytes.length - offset, offset);
      if (!bytesRead) break;
      offset += bytesRead;
    }
    if (offset > info.size) throw new Error('The file changed while it was being read; read it again.');
    const content = new TextDecoder('utf-8', { fatal: true }).decode(bytes.subarray(0, offset));
    if (content.includes('\0')) throw new Error('Only UTF-8 text files can be read.');
    return content;
  } finally { await file.close(); }
}

function textPage(content, startLine = 1, startColumn = 1) {
  if (!Number.isSafeInteger(startLine) || startLine < 1 || !Number.isSafeInteger(startColumn) || startColumn < 1) {
    throw new Error('start_line and start_column must be positive integers.');
  }
  let lineOffset = 0;
  for (let line = 1; line < startLine; line += 1) {
    lineOffset = content.indexOf('\n', lineOffset) + 1;
    if (!lineOffset) throw new Error('start_line is beyond the end of the file.');
  }
  const offset = lineOffset + startColumn - 1;
  const lineEnd = content.indexOf('\n', lineOffset);
  if (offset > (lineEnd < 0 ? content.length : lineEnd)) throw new Error('start_column is beyond the end of the line.');
  let cut = Math.min(offset + MAX_TOOL_OUTPUT - 120, content.length);
  if (cut === content.length) return content.slice(offset);
  if (/^[\uDC00-\uDFFF]$/u.test(content[cut])) cut -= 1; // Keep surrogate pairs together.
  const page = content.slice(offset, cut);
  const nextLine = startLine + (page.match(/\n/gu)?.length ?? 0);
  const lastLineBreak = page.lastIndexOf('\n');
  const nextColumn = lastLineBreak < 0 ? startColumn + page.length : page.length - lastLineBreak;
  return `${page}\n\n[More text: call read_file with start_line ${nextLine}, start_column ${nextColumn}.]`;
}

function documentFilename(value) {
  if (typeof value !== 'string' || !/^[^<>:"/\\|?*\u0000-\u001F]+\.md$/iu.test(value) || path.basename(value) !== value) {
    throw new Error('The workflow output must be a Markdown filename in the project root.');
  }
  return value;
}

function sameWorkspacePath(left, right) {
  return process.platform === 'win32' ? left.toLowerCase() === right.toLowerCase() : left === right;
}

async function listDirectory(absolute, signal) {
  const directory = await opendir(absolute);
  const entries = [];
  let more = false;
  let length = 0;
  try {
    for await (const entry of directory) {
      signal.throwIfAborted();
      if (!entry.isFile() && !entry.isDirectory()) continue;
      const label = `${JSON.stringify(entry.name)}${entry.isDirectory() ? ' (folder)' : ''}`;
      length += label.length + 1;
      if (entries.length === MAX_DIRECTORY_ENTRIES || length > MAX_TOOL_OUTPUT - 80) {
        more = true;
        break;
      }
      entries.push(label);
    }
  } finally {
    await directory.close().catch(error => { if (error.code !== 'ERR_DIR_CLOSED') throw error; });
  }
  return entries.sort().join('\n') + (more ? '\n[More entries are present. List a specific subdirectory.]' : '') || '(Empty directory)';
}

function parseToolArguments(call) {
  try {
    const value = JSON.parse(call.function.arguments || '{}');
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error();
    return value;
  } catch {
    throw new Error(`Tool ${call.function.name} sent invalid JSON arguments.`);
  }
}

function makeUserMessage(text, attachments) {
  const attachmentLine = attachments?.length
    ? `\n\nAttached files (paths available to read_file):\n${attachments.map((file) => `- ${file}`).join('\n')}`
    : '';
  return { role: 'user', content: `${text}${attachmentLine}` };
}

class OpenAiCompatibleSession extends EventEmitter {
  constructor({ connection, apiKey, workspacePath, fetchImpl = globalThis.fetch, onLog = () => {}, options = {} }) {
    super();
    if (typeof fetchImpl !== 'function') throw new Error('This runtime requires the built-in fetch API.');
    if (!connection || !connection.id || !connection.baseUrl) throw new Error('The selected model connection is unavailable.');
    if (!['openai-compatible', 'openai-responses', 'anthropic-messages'].includes(connection.transport)) throw new Error('The selected model connection uses an unsupported transport.');
    if (!apiKey) throw new Error('Add an API key for this model connection before starting a chat.');
    this.connection = {
      id: connection.id,
      transport: connection.transport,
      baseUrl: connection.baseUrl,
      ...(connection.defaultModel ? { defaultModel: connection.defaultModel } : {}),
    };
    this.apiKey = apiKey;
    this.workspacePath = workspacePath;
    this.skillRuntime = createSkillRuntime(workspacePath, { globalSkillsRoot: globalSkillsRoot() });
    this.attachedFiles = new Set();
    this.fetch = fetchImpl;
    this.onLog = onLog;
    const resumeState = options.resumeState;
    this.model = options.model || resumeState?.model || connection.defaultModel;
    this.effort = options.effort ?? resumeState?.effort ?? 'auto';
    if (!this.model) throw new Error('Choose a model for this connection first.');
    this.approval = options.approval || 'ask';
    this.#validateApproval(this.approval);
    this.documentOutput = options.documentOutput === undefined ? undefined : documentFilename(options.documentOutput);
    this.artifactOutputs = Array.isArray(options.artifactOutputs) ? [...options.artifactOutputs] : undefined;
    const defaultInstructions = (options.instructions || "You are Carb, the coding assistant in this workspace. When asked who you are, introduce yourself as Carb. Identify your model or provider separately when known.\n\nUse the workspace tools to complete the task. List and read files as needed, carry out the requested changes, then verify the results. Report actions only when the tools confirm them. The application handles any approval prompts.") + (this.artifactOutputs ? `\n\n${artifactTaskInstructions(true)}` : '');
    this.messages = restoreMessages(resumeState?.messages, defaultInstructions);
    const completionSystem = this.messages.find(message => message.role === 'system');
    if (completionSystem && !String(completionSystem.content).includes(REPLY_STYLE_INSTRUCTIONS)) completionSystem.content += '\n\n' + REPLY_STYLE_INSTRUCTIONS;
    const skillSystem = this.messages.find(message => message.role === 'system');
    if (skillSystem && !String(skillSystem.content).includes(skillRuntimeInstructions)) skillSystem.content += '\n\n' + skillRuntimeInstructions;
    const clarification = "When a missing detail would materially change the result, use the available structured user-input tool (request_user_input, AskUserQuestion, or the equivalent) before proceeding. Ask at most three concise questions in the user's language, suggest two to four meaningful choices when possible, and always allow a separate custom answer. Do not invent choices if none are useful. If the tool is unavailable, ask the same concise questions in the chat and wait for the reply. Do not ask about routine implementation choices.";
    const system = this.messages.find(message => message.role === 'system');
    if (system && !system.content.includes('always allow a separate custom answer')) system.content += '\n\n' + clarification;
    this.thread = {
      id: options.threadId || `api-${randomUUID()}`,
      provider: 'api',
      connectionId: connection.id,
      workspacePath,
      createdAt: Number.isFinite(resumeState?.createdAt) ? resumeState.createdAt : now(),
      ...(this.model ? { model: this.model } : {}),
    };
    this.capabilities = {
      steer: false,
      fork: false,
      interrupt: true,
      reasoningItems: false,
      approvals: true,
      askFirst: true,
      userInput: true,
      autoReview: false,
      images: false,
      imageFiles: true,
    };
    this.activeController = undefined;
    this.pendingApprovals = new Map();
    this.pendingUserInputs = new Map();
    this.disposed = false;
    this.turnSequence = Number.isSafeInteger(resumeState?.turnSequence) && resumeState.turnSequence >= 0 ? resumeState.turnSequence : 0;
  }

  async start() { return this.thread; }

  snapshot() {
    return {
      version: 1,
      model: this.model,
      effort: this.effort,
      createdAt: this.thread.createdAt,
      turnSequence: this.turnSequence,
      messages: structuredClone(this.messages),
    };
  }

  sendTurn(threadId, text, attachments = [], turnOptions = {}) {
    if (this.disposed) throw new Error('The model connection session has been closed.');
    if (threadId !== this.thread.id) throw new Error('The API runtime received an unexpected thread id.');
    if (this.activeController) throw new Error('This API model is already answering.');
    if (turnOptions.model && turnOptions.model !== this.model) {
      this.model = turnOptions.model;
      this.thread.model = turnOptions.model;
    }
    if (turnOptions.effort !== undefined) {
      if (!['auto', 'low', 'medium', 'high'].includes(turnOptions.effort)) throw new Error('Unsupported reasoning effort. Choose auto, low, medium or high.');
      this.effort = turnOptions.effort;
    }
    const turnId = `turn-${++this.turnSequence}-${randomUUID()}`;
    for (const file of attachments) {
      if (typeof file === 'string' && path.isAbsolute(file)) this.attachedFiles.add(path.resolve(file));
    }
    this.messages.push(makeUserMessage(text, attachments));
    const controller = new AbortController();
    this.activeController = controller;
    const document = this.documentOutput === undefined ? undefined : { filename: this.documentOutput, written: false };
    const artifact = this.artifactOutputs ? { paths: [...this.artifactOutputs], report: undefined } : undefined;
    this.documentOutput = undefined;
    this.artifactOutputs = undefined;
    queueMicrotask(() => void this.#runTurn(turnId, controller, document, artifact).finally(() => {
      if (this.activeController === controller) this.activeController = undefined;
    }));
    return turnId;
  }

  interrupt() { this.activeController?.abort(new DOMException('Interrupted by the user.', 'AbortError')); }
  setApproval(approval) {
    this.#validateApproval(approval);
    this.approval = approval;
  }


  respondToUserInput(id, answers) {
    const pending = this.pendingUserInputs.get(id);
    if (!pending) throw new Error('This question is no longer awaiting an answer.');
    const normalized = Object.create(null);
    if (!answers || typeof answers !== 'object' || Array.isArray(answers)) throw new Error('Invalid answers.');
    for (const question of pending.questions) {
      const values = answers[question.id];
      if (!Array.isArray(values) || !values.length || values.length > 16 || values.some(value => typeof value !== 'string' || !value.trim() || value.length > 12000)) throw new Error('Please answer every question.');
      normalized[question.id] = values.map(value => value.trim());
    }
    pending.finish(normalized);
  }

  async requestUserInput(turnId, args, signal) {
    if (!Array.isArray(args.questions) || !args.questions.length || args.questions.length > 3) throw new Error('Ask between one and three questions.');
    const ids = new Set();
    const questions = args.questions.map((question, index) => {
      if (!question || typeof question.question !== 'string' || !question.question.trim() || question.question.length > 2000) throw new Error('A concise question is required.');
      const id = typeof question.id === 'string' && question.id.trim() ? question.id.trim() : 'question-' + (index + 1);
      if (id.length > 120 || ids.has(id)) throw new Error('Question IDs must be unique.');
      ids.add(id);
      const options = (Array.isArray(question.options) ? question.options : []).slice(0, 4).map(option => {
        if (!option || typeof option.label !== 'string' || !option.label.trim() || option.label.length > 400) throw new Error('Invalid question option.');
        return { label: option.label.trim(), description: typeof option.description === 'string' ? option.description.slice(0, 1000) : option.label.trim() };
      });
      if (new Set(options.map(option => option.label)).size !== options.length) throw new Error('Question choices must be distinct.');
      return { id, header: typeof question.header === 'string' && question.header.trim() ? question.header.slice(0, 120) : 'Question ' + (index + 1), question: question.question.trim(), options, allowOther: true, multiSelect: question.multiSelect === true, secret: question.secret === true };
    });
    signal.throwIfAborted();
    const id = 'input-' + randomUUID();
    return await new Promise((resolve, reject) => {
      let settled = false;
      const finish = (value, error) => {
        if (settled) return;
        settled = true;
        this.pendingUserInputs.delete(id);
        signal.removeEventListener('abort', abort);
        this.emit('event', { type: 'user_input.resolved', id });
        if (error) reject(error); else resolve(JSON.stringify({ answers: value }));
      };
      const abort = () => finish(undefined, signal.reason ?? new Error('Question cancelled.'));
      this.pendingUserInputs.set(id, { questions, finish });
      signal.addEventListener('abort', abort, { once: true });
      if (signal.aborted) { abort(); return; }
      this.emit('event', { type: 'user_input.requested', request: { id, turnId, questions, autoResolutionMs: null, createdAt: now() } });
    });
  }

  respondToApproval(id, decision) {
    const pending = this.pendingApprovals.get(id);
    if (!pending) return;
    this.pendingApprovals.delete(id);
    pending.resolve(decision);
  }

  async dispose() {
    this.disposed = true;
    this.interrupt();
    for (const pending of this.pendingApprovals.values()) pending.resolve('abort');
    this.pendingApprovals.clear();
  }

  async #runTurn(turnId, controller, document, artifact) {
    this.emit('event', { type: 'turn.started', turn: { id: turnId, threadId: this.thread.id, status: 'running', createdAt: now() } });
    const userItemId = `item-${randomUUID()}`;
    const userText = this.messages.at(-1)?.content ?? '';
    this.#emitItem(turnId, { id: userItemId, turnId, type: 'message', status: 'started', role: 'user', text: '', createdAt: now() });
    this.#emitDelta(turnId, userItemId, userText);
    this.#emitItem(turnId, { id: userItemId, turnId, type: 'message', status: 'completed', role: 'user', text: userText, createdAt: now() });
    let failedToolCalls = 0;
    let finalStatus = 'completed';
    try {
      if (document) { document.startedAt = Date.now(); document.toolCalls = 0; document.path = await resolveWorkspacePath(this.workspacePath, document.filename, { allowMissing: true }); }
      for (;;) { // Carb: continue until completion or cancellation
        if (controller.signal.aborted) throw controller.signal.reason;
        const response = await this.#complete(turnId, controller.signal, document);
        const choice = response.message;
        if (!choice) throw new Error('The model returned an empty response.');
        this.messages.push({
          role: 'assistant',
          ...(typeof choice.content === 'string' ? { content: choice.content } : { content: '' }),
          ...(typeof choice.reasoning_content === 'string' ? { reasoning_content: choice.reasoning_content } : {}),
          ...(choice.tool_calls?.length ? { tool_calls: choice.tool_calls } : {}),
        });
        const calls = choice.tool_calls ?? [];
        if (!calls.length) break;
        // Balance every tool-call group before persisting the transcript. On an
        // interruption or limit, a later prompt must still be a valid request.
        let toolError;
        for (const call of calls) {
          let result = 'Tool error: this call was skipped because the turn stopped.';
          try {
            if (!toolError) {
              controller.signal.throwIfAborted();
              const execution = await this.#executeTool(turnId, call, controller.signal, document, artifact);
              result = execution.result;
              if (execution.failed) failedToolCalls += 1;
            }
          } catch (error) { toolError = error; }
          this.messages.push({ role: 'tool', tool_call_id: call.id, content: result });
        }
        if (toolError) throw toolError;
      }
      if (document) {
        if (!document.written) throw new Error(`The model did not create ${document.filename}. Use a model that supports tool calls and run the workflow again.`);
        const output = await resolveWorkspacePath(this.workspacePath, document.filename);
        const readback = await readTextFile(output, controller.signal);
        const receipt = verifyDocumentReadback(readback, document, /[\u3400-\u9fff]/u.test(userText));
        this.#emitAssistantText(turnId, receipt);
        this.messages.push({ role: 'assistant', content: receipt });
      }
      if (artifact) {
        controller.signal.throwIfAborted();
        const report = await verifyArtifactSet(this.workspacePath, artifact.paths);
        controller.signal.throwIfAborted();
        const receipt = artifactOutputReceipt(report, this.workspacePath, /[\u3400-\u9fff]/u.test(userText));
        this.#emitAssistantText(turnId, receipt);
        this.messages.push({ role: 'assistant', content: receipt });
      }
    } catch (error) {
      finalStatus = controller.signal.aborted ? 'interrupted' : 'failed';
      if (!controller.signal.aborted) {
        const message = error instanceof Error ? error.message : String(error);
        this.onLog(`[api-runtime] ${message}`);
        this.emit('event', { type: 'thread.error', threadId: this.thread.id, message });
        this.#emitAssistantText(turnId, `Request failed: ${message}`, 'failed');
      }
    } finally {
      for (const [id, pending] of this.pendingApprovals) {
        this.pendingApprovals.delete(id);
        pending.resolve('abort');
        this.emit('event', { type: 'approval.resolved', id });
      }
      this.emit('event', { type: 'turn.completed', turnId, status: finalStatus, completedAt: now(), toolStats: { failedToolCalls } });
    }
  }

  async #complete(turnId, signal, document) {
    const request = requestFor(this.connection, this.apiKey, this.model, this.messages, document, this.effort);
    const controller = new AbortController();
    const forwardAbort = () => controller.abort(signal.reason);
    signal.addEventListener('abort', forwardAbort, { once: true });
    if (signal.aborted) forwardAbort();
    let idleTimer;
    const resetIdleTimer = () => {
      clearTimeout(idleTimer);
      idleTimer = setTimeout(() => controller.abort(new Error('The model service stopped responding. Try again or choose a different model.')), SERVICE_IDLE_MS);
      idleTimer.unref?.();
    };
    const cleanup = () => {
      clearTimeout(idleTimer);
      signal.removeEventListener('abort', forwardAbort);
    };
    resetIdleTimer();
    let response;
    try {
      response = await this.fetch(request.url, {
        method: 'POST',
        redirect: 'error',
        signal: controller.signal,
        headers: { ...request.headers, 'Content-Type': 'application/json', Accept: 'text/event-stream, application/json' },
        body: JSON.stringify(request.body),
      });
    } catch (error) {
      cleanup();
      if (controller.signal.aborted) throw controller.signal.reason;
      throw new Error('Could not reach the model service. Check the connection URL and network access.');
    }
    if (!response.ok) {
      cleanup();
      void response.body?.cancel().catch(() => {});
      const hint = response.status === 401 || response.status === 403 ? 'Check the API key and its permission to use this model.'
        : response.status === 429 ? 'Check the provider rate limit and account quota.'
        : response.status === 404 ? 'Check the model ID and service endpoint.' : 'Check the selected model and provider settings.';
      throw new Error(`The model service returned HTTP ${response.status}. ${hint}`);
    }
    if (!response.body) {
      cleanup();
      throw new Error('The model service returned no response stream.');
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffered = '';
    let receivedBytes = 0;
    let streamDone = false;
    const json = /(?:application\/json|\+json)\b/iu.test(response.headers.get('content-type') ?? '');
    const message = emptyAssistantMessage();
    let textItemId;
    const appendText = (delta) => {
      if (typeof delta !== 'string' || !delta) return;
      message.content += delta;
      textItemId ??= `item-${randomUUID()}`;
      if (message.content === delta) {
        this.#emitItem(turnId, { id: textItemId, turnId, type: 'message', status: 'started', role: 'assistant', text: '', createdAt: now() });
      }
      this.#emitDelta(turnId, textItemId, delta);
    };
    const appendReasoning = (delta) => {
      if (typeof delta === 'string') message.reasoning_content = (message.reasoning_content ?? '') + delta;
    };
    const acceptChunk = (chunk, eventName) => {
      if (!chunk || typeof chunk !== 'object') return;
      const type = chunk.type || eventName;
      if (chunk.error || ['error', 'response.failed', 'response.incomplete'].includes(type)) {
        throw new Error('The model service reported an incomplete or failed response. Check the selected model and provider settings.');
      }

      if (this.connection.transport === 'openai-compatible') {
        const choice = chunk.choices?.[0];
        const delta = choice?.delta ?? choice?.message;
        if (choice?.finish_reason === 'length' || choice?.finish_reason === 'content_filter') throw new Error('The model response stopped before it could finish.');
        appendText(delta?.content);
        appendReasoning(delta?.reasoning_content);
        for (const part of delta?.tool_calls ?? []) {
          const index = Number.isInteger(part.index) ? part.index : message.tool_calls.length;
          appendToolCall(message, index, {
            id: part.id,
            name: part.function?.name,
            nameDelta: true,
            arguments: part.function?.arguments,
          });
        }
        return;
      }

      if (this.connection.transport === 'openai-responses') {
        if (type === 'response.output_text.delta') appendText(chunk.delta);
        else if (type === 'response.output_item.added' || type === 'response.output_item.done') {
          const item = chunk.item;
          if (item?.type === 'function_call') {
            const index = Number.isInteger(chunk.output_index) ? chunk.output_index : message.tool_calls.length;
            const existing = message.tool_calls[index];
            appendToolCall(message, index, {
              id: item.call_id || item.id,
              name: item.name,
              ...(item.arguments !== undefined && !existing?.function.arguments ? { input: item.arguments } : {}),
            });
          }
        } else if (type === 'response.function_call_arguments.delta') {
          const index = Number.isInteger(chunk.output_index) ? chunk.output_index : message.tool_calls.length;
          appendToolCall(message, index, { id: chunk.call_id, arguments: chunk.delta });
        } else if (type === 'response.function_call_arguments.done') {
          const index = Number.isInteger(chunk.output_index) ? chunk.output_index : message.tool_calls.length;
          const current = message.tool_calls[index];
          if (current && typeof chunk.arguments === 'string') current.function.arguments = chunk.arguments;
        } else if (type === 'response.completed' || type === 'response.done' || Array.isArray(chunk.output)) {
          const output = chunk.response?.output ?? chunk.output ?? [];
          for (let index = 0; index < output.length; index += 1) {
            const item = output[index];
            if (item.type === 'message' && !message.content) {
              for (const part of item.content ?? []) if (part.type === 'output_text') appendText(part.text);
            } else if (item.type === 'function_call') {
              const existing = message.tool_calls[index];
              appendToolCall(message, index, {
                id: item.call_id || item.id,
                name: item.name,
                ...(!existing?.function.arguments && item.arguments !== undefined ? { input: item.arguments } : {}),
              });
            }
          }
          streamDone = true;
        }
        return;
      }

      if (type === 'content_block_start') {
        const block = chunk.content_block;
        if (block?.type === 'tool_use') {
          appendToolCall(message, chunk.index ?? message.tool_calls.length, {
            id: block.id, name: block.name,
            ...(Object.keys(block.input ?? {}).length ? { input: block.input } : {}),
          });
        } else if (block?.type === 'text') appendText(block.text);
      } else if (type === 'content_block_delta') {
        const delta = chunk.delta;
        if (delta?.type === 'text_delta') appendText(delta.text);
        else if (delta?.type === 'input_json_delta') {
          appendToolCall(message, chunk.index ?? message.tool_calls.length, { arguments: delta.partial_json });
        }
      } else if (type === 'message_start' || type === 'message' || Array.isArray(chunk.content)) {
        const content = chunk.message?.content ?? chunk.content ?? [];
        for (let index = 0; index < content.length; index += 1) {
          const item = content[index];
          if (item.type === 'tool_use') appendToolCall(message, index, { id: item.id, name: item.name, input: item.input ?? {} });
          else if (item.type === 'text') appendText(item.text);
        }
      } else if (type === 'message_delta' && ['error', 'max_tokens'].includes(chunk.delta?.stop_reason)) {
        throw new Error('The model response stopped before it could finish.');
      } else if (type === 'message_stop') streamDone = true;
    };
    const acceptFrame = (frame) => {
      const lines = frame.split(/\r?\n/u);
      const eventName = lines.find((line) => line.startsWith('event:'))?.slice(6).trim();
      const payload = lines.filter((line) => line.startsWith('data:')).map((line) => line.slice(5).trim()).join('\n');
      if (!payload) return;
      if (payload === '[DONE]') { streamDone = true; return; }
      let chunk;
      try { chunk = JSON.parse(payload); }
      catch { throw new Error('The model service returned invalid streaming data.'); }
      acceptChunk(chunk, eventName);
    };
    try {
      while (!streamDone) {
        controller.signal.throwIfAborted();
        const { value, done } = await reader.read();
        if (done) break;
        resetIdleTimer();
        receivedBytes += value.byteLength;
        if (receivedBytes > MAX_RESPONSE_BYTES) throw new Error('The model response exceeded the 8 MB limit.');
        buffered += decoder.decode(value, { stream: true });
        if (json) continue;
        let match;
        while (!streamDone && (match = /\r?\n\r?\n/u.exec(buffered))) {
          const frame = buffered.slice(0, match.index);
          buffered = buffered.slice(match.index + match[0].length);
          acceptFrame(frame);
        }
      }
      buffered += decoder.decode();
      if (json) {
        let chunk;
        try { chunk = JSON.parse(buffered); }
        catch { throw new Error('The model service returned invalid JSON.'); }
        acceptChunk(chunk);
      } else if (!streamDone && buffered.trim()) acceptFrame(buffered);
    } catch (error) {
      void reader.cancel().catch(() => {});
      if (controller.signal.aborted) throw controller.signal.reason;
      if (textItemId) this.#emitItem(turnId, { id: textItemId, turnId, type: 'message', status: 'failed', role: 'assistant', text: message.content, createdAt: now() });
      throw error;
    } finally {
      if (streamDone) void reader.cancel().catch(() => {});
      cleanup();
      reader.releaseLock();
    }
    const calls = message.tool_calls.filter(Boolean);
    if (calls.some(call => !call.id || !call.function.name) || new Set(calls.map(call => call.id)).size !== calls.length) {
      throw new Error('The model service returned incomplete or duplicate tool calls.');
    }
    if (!message.content && !calls.length) throw new Error('The model service returned no message content or tool calls.');
    if (textItemId) {
      this.#emitItem(turnId, { id: textItemId, turnId, type: 'message', status: 'completed', role: 'assistant', phase: 'final_answer', text: message.content, createdAt: now() });
    }
    message.tool_calls = calls;
    return { message };
  }

  async #executeTool(turnId, call, signal, document, artifact) {
    if (document) document.toolCalls += 1;
    const itemId = `item-${randomUUID()}`;
    const item = { id: itemId, turnId, type: 'tool_call', status: 'started', text: call.function.name, createdAt: now() };
    this.#emitItem(turnId, item);
    let result;
    let failed = false;
    try {
      const args = parseToolArguments(call);
      signal.throwIfAborted();
      if (call.function.name === 'artifact_inspect') {
        if (!artifact) throw new Error('This task does not have a five-format output contract.');
        if (!Array.isArray(args.paths)) throw new Error('artifact_inspect requires five output paths.');
        const contractPaths = paths => paths.map(value => typeof value === 'string' ? value.replaceAll('\\', '/') : '').sort();
        if (JSON.stringify(contractPaths(args.paths)) !== JSON.stringify(contractPaths(artifact.paths))) throw new Error('artifact_inspect paths must match the output contract for this task.');
        artifact.report = await verifyArtifactSet(this.workspacePath, args.paths);
        result = JSON.stringify({ ok: true, count: artifact.report.count, records: artifact.report.records.map(item => ({ path: item.path, kind: item.kind, bytes: item.bytes, sha256: item.sha256 })) });
      } else if (call.function.name === 'skill_list') {
        result = JSON.stringify(await this.skillRuntime.list(args, signal));
      } else if (call.function.name === 'skill_read') {
        result = JSON.stringify(await this.skillRuntime.read(args, signal));
      } else if (call.function.name === 'request_user_input') {
        result = await this.requestUserInput(turnId, args, signal);
      } else if (call.function.name === 'read_file') {
        let absolute;
        const selected = typeof args.path === 'string' && path.isAbsolute(args.path) ? path.resolve(args.path) : undefined;
        if (selected && this.attachedFiles.has(selected)) {
          const info = await lstat(selected);
          if (!info.isFile() || info.isSymbolicLink() || info.nlink > 1) throw new Error('Only regular attached files without links can be read.');
          absolute = selected;
        } else {
          absolute = await resolveWorkspacePath(this.workspacePath, args.path);
        }
        const content = await readTextFile(absolute, signal);
        result = textPage(content, args.start_line, args.start_column);
      } else if (call.function.name === 'list_directory') {
        const absolute = await resolveWorkspacePath(this.workspacePath, args.path, { directory: true });
        result = await listDirectory(absolute, signal);
      } else if (call.function.name === 'write_file') {
        if (typeof args.content !== 'string') throw new Error('The file contents must be text.');
        if (Buffer.byteLength(args.content, 'utf8') > MAX_FILE_BYTES) throw new Error('The proposed file is larger than 1 MB.');
        const absolute = await resolveWorkspacePath(this.workspacePath, args.path, { allowMissing: true });
        let before = '';
        if (document) {
          if (!sameWorkspacePath(absolute, document.path)) throw new Error(`This workflow can only create ${document.filename}.`);
          if (document.written) throw new Error('The workflow output is already written. Use read_file to verify it.');
          if (!args.content.trim() || args.content.includes('\0')) throw new Error('The workflow output must contain Markdown text.');
          signal.throwIfAborted();
          const temp = path.join(path.dirname(absolute), `.carb-${randomUUID()}.tmp`);
          try {
            await writeFile(temp, args.content, { encoding: 'utf8', flag: 'wx', mode: 0o600 });
            signal.throwIfAborted();
            // Link a complete file into place atomically without replacing any
            // existing output. The temporary link is removed before reads resume.
            await link(temp, absolute);
          }
          catch (error) {
            if (error?.code === 'EEXIST') throw new Error(`The output ${document.filename} already exists and was not changed.`);
            throw error;
          } finally { await unlink(temp).catch(() => {}); }
          document.expectedDigest = documentDigest(args.content);
          document.written = true;
        } else {
          await this.#requestApproval({ id: `approval-${randomUUID()}`, kind: 'file_change', reason: 'The model wants to write this file.', path: absolute, createdAt: now() }, signal);
          signal.throwIfAborted();
          const confirmed = await resolveWorkspacePath(this.workspacePath, args.path, { allowMissing: true });
          if (!sameWorkspacePath(confirmed, absolute)) throw new Error('The target file changed while the action was awaiting approval.');
          before = await readTextFile(absolute, signal).catch(error => error?.code === 'ENOENT' ? '' : Promise.reject(error));
          await mkdir(path.dirname(absolute), { recursive: true });
          await resolveWorkspacePath(this.workspacePath, args.path, { allowMissing: true });
          const temp = path.join(path.dirname(absolute), `.carb-${randomUUID()}.tmp`);
          try {
            await writeFile(temp, args.content, { encoding: 'utf8', flag: 'wx' });
            signal.throwIfAborted();
            await rename(temp, absolute);
          } finally { await unlink(temp).catch(() => {}); }
        }
        const beforeLines = before.length ? before.split(/\r?\n/u).length : 0;
        const afterLines = args.content.length ? args.content.split(/\r?\n/u).length : 0;
        this.#emitItem(turnId, { id: `item-${randomUUID()}`, turnId, type: 'file_change', status: 'completed', path: absolute, linesAdded: Math.max(0, afterLines - beforeLines), linesRemoved: Math.max(0, beforeLines - afterLines), createdAt: now() });
        result = `File written successfully: ${path.relative(this.workspacePath, absolute)}.`;
      } else if (call.function.name === 'run_command') {
        if (document) throw new Error('Shell commands are disabled for this document workflow.');
        if (typeof args.command !== 'string' || !args.command.trim()) throw new Error('A command is required.');
        await this.#requestApproval({ id: `approval-${randomUUID()}`, kind: 'command', reason: 'The model wants to run a command in the active workspace.', command: args.command, cwd: this.workspacePath, createdAt: now() }, signal);
        const commandResult = await this.#runCommand(turnId, args.command, signal);
        result = commandResult.result;
        failed = commandResult.failed;
      } else {
        throw new Error(`The model requested an unsupported tool: ${call.function.name}`);
      }
    } catch (error) {
      failed = true;
      result = `Tool error: ${error instanceof Error ? error.message : String(error)}`;
    }
    const completed = { ...item, status: failed ? 'failed' : 'completed', text: `${call.function.name}: ${result.slice(0, MAX_TOOL_OUTPUT)}`, createdAt: now() };
    this.#emitItem(turnId, completed);
    signal.throwIfAborted();
    return { result: result.slice(0, MAX_TOOL_OUTPUT), failed };
  }

  async #requestApproval(request, signal) {
    // Match Harness approval semantics: Auto still asks before shell commands,
    // while file writes only need a prompt in Ask mode. Full explicitly grants
    // both. Auto-review is rejected because this runtime has no reviewer.
    const required = request.kind === 'command'
      ? this.approval === 'ask' || this.approval === 'auto'
      : request.kind === 'file_change' && this.approval === 'ask';
    if (!required) return;
    if (signal.aborted) throw signal.reason;
    this.emit('event', { type: 'approval.requested', request });
    const decision = await new Promise((resolve) => {
      const onAbort = () => {
        this.pendingApprovals.delete(request.id);
        resolve('abort');
      };
      this.pendingApprovals.set(request.id, {
        resolve: (value) => {
          signal.removeEventListener('abort', onAbort);
          resolve(value);
        },
      });
      signal.addEventListener('abort', onAbort, { once: true });
      if (signal.aborted) onAbort();
    });
    this.emit('event', { type: 'approval.resolved', id: request.id });
    if (!['approve', 'approve-session'].includes(decision)) throw new Error('The user did not approve this action.');
    if (decision === 'approve-session') this.approval = 'auto';
  }

  #validateApproval(approval) {
    if (approval === 'auto-review') {
      throw new Error('The API-compatible runtime does not support automatic approval review. Choose Ask, Auto, or Full.');
    }
    if (!['ask', 'auto', 'full'].includes(approval)) {
      throw new Error('The API-compatible runtime received an unsupported approval mode.');
    }
  }

  async #runCommand(turnId, command, signal) {
    const itemId = `item-${randomUUID()}`;
    this.#emitItem(turnId, { id: itemId, turnId, type: 'command', status: 'started', command, createdAt: now() });
    const isWindows = process.platform === 'win32';
    // Carb: pass cmd syntax verbatim inside its required outer quotes.
    const shellArgs = isWindows ? ['/d', '/s', '/c', '"' + command + '"'] : ['-lc', command];
    const child = spawn(isWindows ? process.env.ComSpec || 'cmd.exe' : '/bin/sh', shellArgs, {
      cwd: this.workspacePath,
      shell: false,
      windowsVerbatimArguments: isWindows,
      windowsHide: true,
      stdio: ['ignore', 'pipe', 'pipe'],
      env: { ...process.env, HARNESS_WORKSPACE_PATH: this.workspacePath },
    });
    const kill = () => {
      if (child.exitCode !== null || child.signalCode !== null) return;
      const terminate = () => { try { child.kill('SIGTERM'); } catch {} };
      if (!isWindows || !child.pid) { terminate(); return; }
      // cmd.exe owns the command's process tree; cancellation must stop it too.
      const killer = spawn(path.join(process.env.SystemRoot || 'C:\\Windows', 'System32', 'taskkill.exe'), ['/pid', String(child.pid), '/T', '/F'], {
        shell: false, windowsHide: true, stdio: 'ignore',
      });
      killer.once('error', terminate);
      killer.once('exit', code => { if (code !== 0) terminate(); });
    };
    signal.addEventListener('abort', kill, { once: true });
    if (signal.aborted) kill();
    let output = '';
    const append = (chunk) => {
      if (output.length < 16_000) output += chunk.toString('utf8').slice(0, 16_000 - output.length);
    };
    child.stdout.on('data', append);
    child.stderr.on('data', append);
    const exitCode = await new Promise((resolve, reject) => {
      child.once('error', reject);
      child.once('close', resolve);
    }).finally(() => signal.removeEventListener('abort', kill));
    if (signal.aborted) throw signal.reason;
    this.#emitItem(turnId, { id: itemId, turnId, type: 'command', status: exitCode === 0 ? 'completed' : 'failed', command, exitCode, text: output, createdAt: now() });
    return { result: `Exit code: ${exitCode}\n${output}`, failed: exitCode !== 0 };
  }

  #emitItem(turnId, item) { this.emit('event', { type: item.status === 'started' ? 'item.started' : 'item.completed', item }); }
  #emitDelta(turnId, itemId, textDelta) { this.emit('event', { type: 'item.delta', turnId, itemId, textDelta }); }
  #emitAssistantText(turnId, text, status = 'completed') {
    const id = `item-${randomUUID()}`;
    this.#emitItem(turnId, { id, turnId, type: 'message', status: 'started', role: 'assistant', text: '', createdAt: now() });
    this.#emitDelta(turnId, id, text);
    this.#emitItem(turnId, { id, turnId, type: 'message', status, role: 'assistant', phase: 'final_answer', text, createdAt: now() });
  }
}

/**
 * Creates the Harness runtime for one server-owned model connection. The
 * resolver must return { connection, apiKey }; credentials never cross to the renderer.
 */
export function createApiRuntime({ resolveConnection, onLog = () => {}, fetchImpl = globalThis.fetch } = {}) {
  if (typeof resolveConnection !== 'function') throw new TypeError('resolveConnection is required.');
  async function makeSession(threadId, workspacePath, options) {
    if (!options.connectionId) throw new Error('Choose a model connection before starting this chat.');
    const resolved = await resolveConnection(options.connectionId);
    const connection = resolved?.connection ?? resolved;
    const apiKey = resolved?.apiKey ?? connection?.apiKey;
    if (!connection?.enabled) throw new Error('The selected model connection is disabled or missing.');
    if (connection.id !== options.connectionId) throw new Error('The selected model connection does not match the requested connection.');
    const session = new OpenAiCompatibleSession({ connection, apiKey, workspacePath, fetchImpl, onLog, options: { ...options, ...(threadId ? { threadId } : {}) } });
    return { thread: await session.start(), session };
  }
  return {
    start(workspacePath, options = {}) { return makeSession(undefined, workspacePath, options); },
    resume(threadId, workspacePath, options = {}) { return makeSession(threadId, workspacePath, options); },
    async listModels() { return []; },
  };
}

export { OpenAiCompatibleSession, TOOL_DEFINITIONS };
